def tensor_avgpool_kernel(x, pool_size):
    C, H, W = x.shape
    p = pool_size
    out_shape = (C, H // p, W // p)
    out = nl.ndarray(out_shape, dtype=x.dtype, buffer=nl.shared_hbm)
    t = nl.ndarray((C, H, W), dtype=x.dtype, buffer=nl.sbuf)
    nisa.dma_copy(dst=t, src=x)

    # Reshape to (C, H//p, p, W//p, p)
    t_view = t.reshape((C, H // p, p, W // p, p))

    # Sum over the last two dimensions using a loop
    s = nl.ndarray((C, H // p, W // p), dtype=x.dtype, buffer=nl.sbuf)
    for i in range(C):
        for j in range(H // p):
            for k in range(W // p):
                total = 0.0
                for a in range(p):
                    for b in range(p):
                        total += t_view[i, j, a, k, b]
                s[i, j, k] = total

    # Flatten the sum to 1D to allow scalar multiplication
    s_flat = nl.ndarray((C * (H // p) * (W // p)), dtype=x.dtype, buffer=nl.sbuf)
    idx = 0
    for i in range(C):
        for j in range(H // p):
            for k in range(W // p):
                s_flat[idx] = s[i, j, k]
                idx += 1

    # Multiply by 1/(p*p)
    m_flat = nl.ndarray((C * (H // p) * (W // p)), dtype=x.dtype, buffer=nl.sbuf)
    scalar = 1.0 / (p * p)
    for i in range(C * (H // p) * (W // p)):
        m_flat[i] = s_flat[i] * scalar

    # Reshape back to original out_shape
    m = nl.ndarray(out_shape, dtype=x.dtype, buffer=nl.sbuf)
    idx = 0
    for i in range(C):
        for j in range(H // p):
            for k in range(W // p):
                m[i, j, k] = m_flat[idx]
                idx += 1

    nisa.dma_copy(dst=out, src=m)
    return out

